#!/usr/bin/env bash
# Question 1: Worker after a configuration change. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

[[ "$CKA_NODE" == "${Q1_NODE}" ]] || exit 0

case "${Q1_FAULT}" in
  kubelet-kubeconfig-server)
    sed -i -E 's#^([[:space:]]*server: https://[^[:space:]]+):6443$#\1:6444#' /etc/kubernetes/kubelet.conf
    grep -qE -- 'server: https://[^[:space:]]+:6444$' /etc/kubernetes/kubelet.conf || { echo "could not modify /etc/kubernetes/kubelet.conf" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  kubelet-client-ca)
    sed -i -E 's#^([[:space:]]*clientCAFile: /etc/kubernetes/pki/)ca\.crt$#\1ca.pem#' /var/lib/kubelet/config.yaml
    grep -qE -- 'clientCAFile: /etc/kubernetes/pki/ca.pem$' /var/lib/kubelet/config.yaml || { echo "could not modify /var/lib/kubelet/config.yaml" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  runtime-endpoint)
    sed -i -E 's#^containerRuntimeEndpoint: unix:///var/run/containerd/containerd\.sock$#containerRuntimeEndpoint: unix:///var/run/crio/crio.sock#' /var/lib/kubelet/config.yaml
    grep -qE -- '^containerRuntimeEndpoint: unix:///var/run/crio/crio.sock$' /var/lib/kubelet/config.yaml || { echo "could not modify /var/lib/kubelet/config.yaml" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  kubelet-config-flag)
    dropin=$(systemctl show kubelet -p DropInPaths --value | tr ' ' '\n' | grep 10-kubeadm.conf)
    sed -i -E 's#--config=/var/lib/kubelet/config\.yaml#--config=/var/lib/kubelet/kubelet-config.yaml#' "$dropin"
    grep -qE -- '--config=/var/lib/kubelet/kubelet-config.yaml' "$dropin" || { echo "could not modify "$dropin"" >&2; exit 1; }
    systemctl daemon-reload
    systemctl restart kubelet || true
    ;;
  kubelet-kubeconfig-flag)
    dropin=$(systemctl show kubelet -p DropInPaths --value | tr ' ' '\n' | grep 10-kubeadm.conf)
    sed -i -E 's#--kubeconfig=/etc/kubernetes/kubelet\.conf#--kubeconfig=/etc/kubernetes/kubelet.config#' "$dropin"
    grep -qE -- '--kubeconfig=/etc/kubernetes/kubelet.config' "$dropin" || { echo "could not modify "$dropin"" >&2; exit 1; }
    systemctl daemon-reload
    systemctl restart kubelet || true
    ;;
  kubelet-serving-cert)
    printf 'tlsCertFile: /var/lib/kubelet/pki/kubelet-server.crt\ntlsPrivateKeyFile: /var/lib/kubelet/pki/kubelet-server.key\n' >> /var/lib/kubelet/config.yaml
    grep -q '^tlsCertFile: ' /var/lib/kubelet/config.yaml || { echo "could not modify /var/lib/kubelet/config.yaml" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  kubelet-max-pods)
    sed -i '/^maxPods:/d' /var/lib/kubelet/config.yaml
    echo 'maxPods: 2' >> /var/lib/kubelet/config.yaml
    systemctl restart kubelet || true
    ;;
  kubelet-eviction-hard)
    cp -a /var/lib/kubelet/config.yaml /var/lib/kubelet/config.yaml.cka-bak
    sed -i '/^evictionHard:/,/^[^[:space:]]/{ /^evictionHard:/d; /^[[:space:]]/d; }' /var/lib/kubelet/config.yaml || true
    printf '%s\n' 'evictionHard:' '  memory.available: "99%"' >> /var/lib/kubelet/config.yaml
    grep -q 'memory.available: "99%"' /var/lib/kubelet/config.yaml || { echo "could not set evictionHard" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  kubelet-cgroup-driver)
    sed -i -E 's#^([[:space:]]*SystemdCgroup = )true[[:space:]]*$#\1"invalid"#' /etc/containerd/config.toml
    grep -qE -- '^[[:space:]]*SystemdCgroup = "invalid"$' /etc/containerd/config.toml || { echo "could not modify /etc/containerd/config.toml" >&2; exit 1; }
    systemctl restart containerd || true
    systemctl restart kubelet || true
    ;;
  kubelet-resolv-empty)
    sed -i '/^resolvConf:/d' /var/lib/kubelet/config.yaml
    sed -i '/^[[:space:]]*- \/etc\/resolv\.conf\.missing$/d' /var/lib/kubelet/config.yaml || true
    printf '%s\n' 'resolvConf:' '  - /etc/resolv.conf.missing' >> /var/lib/kubelet/config.yaml
    grep -q '/etc/resolv.conf.missing' /var/lib/kubelet/config.yaml
    systemctl restart kubelet || true
    ;;
  kubelet-hairpin-mode)
    sed -i '/^hairpinMode:/d' /var/lib/kubelet/config.yaml
    echo 'hairpinMode: bogus' >> /var/lib/kubelet/config.yaml
    grep -q '^hairpinMode: bogus$' /var/lib/kubelet/config.yaml
    systemctl restart kubelet || true
    ;;
esac
